<!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYGAME – paskola</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="topbar"><div><b>MYGAME</b><span>Verslo simuliatorius</span></div><div class="topstats"><strong>🏦 Finansavimas</strong></div></div><main class="page loan-page"><div class="intro"><div><span class="eyebrow">ĮMONĖS FINANSAI</span><h1>Verslo paskola</h1><p>Pasirink banką, paskolos sumą ir terminą. Bankas automatiškai įvertins įmonės riziką.</p></div></div><?php if($error): ?><div class="loan-alert bad"><?= htmlspecialchars($error) ?></div><?php endif; ?><section class="loan-layout"><div class="card loan-form"><div class="card-head"><div><small>PARAIŠKA</small><strong><?= htmlspecialchars($company['name']??'Įmonė') ?></strong></div></div><form method="post"><label>Bankas<select name="bank_id" required><?php foreach($banks as $b): ?><option value="<?= (int)$b['id'] ?>"><?= htmlspecialchars($b['name']) ?> · <?= number_format((float)$b['min_amount'],0,',',' ') ?>–<?= number_format((float)$b['max_amount'],0,',',' ') ?> €</option><?php endforeach; ?></select></label><label>Paskolos suma<input name="amount" type="text" inputmode="decimal" value="25000" autocomplete="off" required></label><label>Terminas mėnesiais<input name="months" type="text" inputmode="numeric" value="60" autocomplete="off" required></label><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf) ?>"><button class="start">Pateikti bankui <span>→</span></button></form></div><aside class="card loan-company"><small>ĮMONĖS RODIKLIAI</small><h2><?= htmlspecialchars($company['name']??'') ?></h2><div class="stats"><div><span>Pinigai</span><strong><?= number_format((float)($company['cash']??0),0,',',' ') ?> €</strong></div><div><span>Turtas</span><strong><?= number_format((float)($company['assets']??0),0,',',' ') ?> €</strong></div><div><span>Įsipareigojimai</span><strong><?= number_format((float)($company['liabilities']??0),0,',',' ') ?> €</strong></div><div><span>Mėn. pajamos</span><strong><?= number_format((float)($company['monthly_revenue']??0),0,',',' ') ?> €</strong></div><div><span>Mėn. pelnas</span><strong><?= number_format((float)($company['monthly_profit']??0),0,',',' ') ?> €</strong></div></div></aside><?php if($offer): ?><aside class="card loan-result <?= $offer['approved']?'approved':'rejected' ?>"><small>BANKO SPRENDIMAS</small><h2><?= $offer['approved']?'Paskola patvirtinta':'Paraiška atmesta' ?></h2><p><?= htmlspecialchars($offer['reason']) ?></p><div class="offer-rate"><?= number_format((float)$offer['interest_rate'],2,',',' ') ?>%</div><div class="stats"><div><span>Rizikos balas</span><strong><?= number_format((float)$offer['risk_score'],1,',',' ') ?>/100</strong></div><div><span>Rizikos priedas</span><strong>+<?= number_format((float)$offer['risk_margin'],2,',',' ') ?>%</strong></div><div><span>Mėnesinė įmoka</span><strong><?= number_format((float)$offer['monthly_payment'],2,',',' ') ?> €</strong></div></div></aside><?php endif; ?></section></main></body></html>